1	// CREATOR PARTNER PROGRAM — customer-facing pricing engine (2026-09-26).
2	//
3	// Pure, DB-free arithmetic only, mirroring lib/coupon-order.ts's own split: the
4	// DB lookups (is this customer attached? have they used their first-purchase
5	// discount yet?) live in lib/partner-pricing.ts, which calls these. Keeping the
6	// math here means it can be unit-tested directly (test/partner-discount.test.ts)
7	// without mocking Prisma, exactly how test/coupon-order.test.ts exercises
8	// couponOrderDiscountCents without a database.
9	//
10	// THE RULE (owner's verbatim spec): a customer permanently attached to a partner
11	// (PartnerCustomer, lifetime, one partner per customer) gets:
12	//   - Their FIRST purchase of any real service EXCEPT a domain: 50% off.
13	//   - Every purchase after that, forever (including every renewal): 10% off.
14	// Domains are never discounted by this program, at any tier.
15	
16	/** The owner's verbatim first-purchase rate. Not admin-configurable — a fixed
17	 *  program term, unlike a partner's own `commissionRatePct`. */
18	export const PARTNER_FIRST_PURCHASE_PCT = 50;
19	/** The owner's verbatim recurring rate — every purchase after the first, forever. */
20	export const PARTNER_RECURRING_PCT = 10;
21	
22	export type PartnerDiscountTier = "FIRST" | "RECURRING" | "NONE";
23	
24	/**
25	 * The discount percent a customer's order/renewal should be sold at, given:
26	 *  - `attached`: are they linked to a partner at all (PartnerCustomer exists)?
27	 *  - `partnerActive`: is that partner's status ACTIVE (a PAUSED partner earns no
28	 *    new commission — mirrors partner-commission.ts's own gate — and, by the same
29	 *    logic, a paused partner's customers get no new discount either: pausing a
30	 *    partner must stop BOTH sides of the deal, not just the payout).
31	 *  - `isDomain`: domains are excluded at every tier, first or recurring.
32	 *  - `firstPurchaseAvailable`: true until `PartnerCustomer.firstPurchaseDiscountUsedAt`
33	 *    is set. A RENEWAL is by definition never a customer's first purchase (the
34	 *    server being renewed was itself bought first) — callers pricing a renewal
35	 *    must always pass `false` here, which collapses straight to the recurring tier.
36	 */
37	export function partnerDiscountTier(opts: {
38	  attached: boolean;
39	  partnerActive: boolean;
40	  isDomain: boolean;
41	  firstPurchaseAvailable: boolean;
42	}): PartnerDiscountTier {
43	  if (!opts.attached || !opts.partnerActive || opts.isDomain) return "NONE";
44	  return opts.firstPurchaseAvailable ? "FIRST" : "RECURRING";
45	}
46	
47	export function partnerDiscountPercentForTier(tier: PartnerDiscountTier): number {
48	  if (tier === "FIRST") return PARTNER_FIRST_PURCHASE_PCT;
49	  if (tier === "RECURRING") return PARTNER_RECURRING_PCT;
50	  return 0;
51	}
52	
53	/** Convenience: tier resolution + percent in one call. */
54	export function partnerDiscountPercent(opts: {
55	  attached: boolean;
56	  partnerActive: boolean;
57	  isDomain: boolean;
58	  firstPurchaseAvailable: boolean;
59	}): { tier: PartnerDiscountTier; percent: number } {
60	  const tier = partnerDiscountTier(opts);
61	  return { tier, percent: partnerDiscountPercentForTier(tier) };
62	}
63	
64	/**
65	 * Apply a percent-off to a cents amount, clamped so a corrupt/out-of-range
66	 * percent can never produce a negative charge or a discount bigger than the
67	 * amount itself — same clamp discipline as renewalCharge's retention-offer
68	 * percent and the coupon math in lib/coupon-order.ts.
69	 */
70	export function partnerDiscountCentsFor(amountCents: number, percent: number): number {
71	  const clamped = Math.max(0, Math.min(100, percent));
72	  if (amountCents <= 0 || clamped <= 0) return 0;
73	  return Math.round((amountCents * clamped) / 100);
74	}
