  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
  // so the deploy preview can show it; the redemption itself (count + per-user +
  // per-IP guards) is claimed atomically in placeOrder.
  let couponId: string | null = null;
  let couponDiscountCents = 0;
  let couponLabel = "";
  let couponError = "";
  let couponMaxRedemptions: number | null = null;
  let couponFirstTimeOnly = false;
  let couponExcludeActiveCustomers = false;
  let couponTrialDays: number | null = null;
  const code = (intent.couponCode ?? "").trim().toUpperCase();
  if (code) {
    if (!(await getSettingBool("coupons_enabled", true))) {
      couponError = "Promo codes are currently disabled.";
    } else {
      const coupon = await db.coupon.findUnique({ where: { code } });
      if (!coupon) {
        couponError = "That code isn’t valid.";
      } else {
        const verdict = couponOrderDiscountCents(
          {
            kind: coupon.kind,
            value: coupon.value,
            serviceKind: coupon.serviceKind,
            planSlug: coupon.planSlug,
            maxTermMonths: coupon.maxTermMonths,
            active: coupon.active,
            expiresAt: coupon.expiresAt,
            maxRedemptions: coupon.maxRedemptions,
            timesRedeemed: coupon.timesRedeemed,
            minAmountCents: coupon.minAmountCents,
          },
          {
            serviceKind: "VPS",
            planSlug: plan.slug,
            planMonthlyCents: plan.priceCents,
            termMonths: term.months,
            // Coupon discounts the intro-reduced plan portion, so an intro price and a
            // coupon cannot together drive the plan charge below zero, and a percentage
            // coupon is honestly "% off what you actually pay this term".
            planChargeCents: introFirstTermPlanCents,
          },
          new Date(),
        );
        if (verdict.ok) {
          couponId = coupon.id;
          couponDiscountCents = verdict.discountCents;
          couponLabel = verdict.label;
          couponMaxRedemptions = coupon.maxRedemptions;
          couponFirstTimeOnly = coupon.firstTimeOnly;
          couponExcludeActiveCustomers = coupon.excludeActiveCustomers;
          couponTrialDays = coupon.trialDays;
        } else {
          couponError = verdict.error;
        }
      }
    }
  }

  const preDiscountChargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
  // CREATOR PARTNER PROGRAM: fold in the customer's 50%-off-first-purchase /
  // 10%-off-every-purchase-after discount (0 for the overwhelming majority never
  // attached to a partner). Applied on top of every other discount (intro,
  // coupon) — the customer's LAST price, not a second competing formula — and
  // covers every line (plan, dedicated IP, extra disk, backup): nothing on this
  // side excludes the dedicated IP add-on, only the PARTNER'S COMMISSION does
  // (lib/partner-commission.ts's separate, unrelated exclusion rule).
  const partnerDiscount = await partnerDiscountForNewOrder(opts?.userId);
  const partnerDiscountCents = partnerDiscountCentsFor(preDiscountChargeCents, partnerDiscount.percent);
  const chargeCents = preDiscountChargeCents - partnerDiscountCents;
  // The RECURRING rate this customer's account carries going forward — always the
  // 10% recurring tier (never the 50% first-purchase tier: by the time this order
  // renews, the first-purchase discount will already have been spent, whether it
  // was spent HERE or on some earlier purchase) — used only for the "renews at
  // $X" caption below, via renewalTotalCents.
