 * Pure decision (unit-tested in test/creator-code.test.ts). The order of the
 * checks decides which message a customer sees when more than one applies; the
 * most specific, most actionable one wins.
 */
export function creatorCodeVerdict(facts: {
  code: string;
  couponExists: boolean;
  partner: { id: string; name: string; status: string; userId: string | null } | null;
  customerId: string;
  attachedPartnerId: string | null;
  hasPaidPurchase: boolean;
}): CreatorCodeVerdict {
  const { code, partner } = facts;
  if (!partner || facts.couponExists) return { kind: "none" };
  const refuse = (reason: CreatorCodeRefusal): CreatorCodeVerdict =>
    ({ kind: "refused", code, reason, message: CREATOR_CODE_MESSAGES[reason] });
  if (partner.userId && partner.userId === facts.customerId) return refuse("own");
  if (facts.attachedPartnerId) {
    return facts.attachedPartnerId === partner.id
      ? { kind: "linked-same", code, partnerName: partner.name }
      : refuse("linked");
  }
  if (partner.status !== "ACTIVE") return refuse("inactive");
  if (facts.hasPaidPurchase) return refuse("purchased");
  return { kind: "eligible", code, partnerName: partner.name };
}

/**
 * Has this account bought anything? A PAID (or since REFUNDED — a refund must not
 * reopen the first-purchase window) invoice with a positive total that is not a
 * wallet top-up, the same "is this a real sale" classifier commission accrual uses
 * (lib/partner-commission.ts isCommissionableInvoice) — or any non-free server row.
 * Covers every product (VPS, game, hosting, email, domains, add-ons) because every
 * one of them issues an Invoice.
 */
export async function hasMadePaidPurchase(
  userId: string,
  client: Prisma.TransactionClient | typeof db = db,
): Promise<boolean> {
  const [invoices, servers] = await Promise.all([
    client.invoice.count({
      where: {
        userId,
        status: { in: ["PAID", "REFUNDED"] },
        amountCents: { gt: 0 },
        description: { notIn: [...NON_COMMISSIONABLE_DESCRIPTIONS] },
      },
    }),
    client.server.count({ where: { userId, isFree: false } }),
  ]);
  return invoices > 0 || servers > 0;
}

async function gatherFacts(client: Prisma.TransactionClient | typeof db, userId: string, code: string) {
  const [coupon, partner, attachment, hasPaidPurchase] = await Promise.all([
    client.coupon.findUnique({ where: { code }, select: { id: true } }),
    client.referralPartner.findUnique({
      where: { code },
      select: { id: true, name: true, status: true, userId: true },
    }),
    client.partnerCustomer.findUnique({ where: { customerId: userId }, select: { partnerId: true } }),
    hasMadePaidPurchase(userId, client),
  ]);
  return {
    code,
    couponExists: !!coupon,
    partner,
    customerId: userId,
    attachedPartnerId: attachment?.partnerId ?? null,
    hasPaidPurchase,
  };
}

/** Read-only: what would typing this code into the promo box do for this account? */
export async function resolveCreatorCode(userId: string, rawCode: string): Promise<CreatorCodeVerdict> {
  const code = normalizeCreatorCode(rawCode);
  if (!looksLikeCreatorCode(code)) return { kind: "none" };
  return creatorCodeVerdict(await gatherFacts(db, userId, code));
}

/**
 * Attach the account to the creator whose code this is, re-running every rule
 * inside one transaction. Returns the verdict that applied: `eligible` means the
 * attachment was made by THIS call. A concurrent attach (the UNIQUE customerId)
 * resolves to `linked-same`/`refused: linked` on a re-read, never a crash.
 */
export async function attachCreatorCode(userId: string, rawCode: string): Promise<CreatorCodeVerdict> {
  const code = normalizeCreatorCode(rawCode);
  if (!looksLikeCreatorCode(code)) return { kind: "none" };
  try {
    return await db.$transaction(async (tx) => {
      const verdict = creatorCodeVerdict(await gatherFacts(tx, userId, code));
      if (verdict.kind !== "eligible") return verdict;
      const partner = await tx.referralPartner.findUniqueOrThrow({ where: { code }, select: { id: true } });
      await tx.partnerCustomer.create({ data: { partnerId: partner.id, customerId: userId } });
      return verdict;
    });
  } catch (e) {
    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") {
      return resolveCreatorCode(userId, code);
    }
    throw e;
  }
}

/**
 * Register-page check: a brand-new account has no partner and no purchase, so the
 * only question is whether the typed code is a real, ACTIVE partner code. The
 * attachment itself then goes through attachCustomerToPartnerByCode, exactly like
 * the cookie path.
 */
export async function signupCreatorCode(
  rawCode: string,
): Promise<{ ok: true; code: string; partnerName: string } | { ok: false; error: string }> {
  const code = normalizeCreatorCode(rawCode);
  const invalid = "That creator code isn't valid. Check the spelling, or clear the field to sign up without one.";
  if (!looksLikeCreatorCode(code)) return { ok: false, error: invalid };
  const partner = await db.referralPartner.findUnique({ where: { code }, select: { name: true, status: true } });
  if (!partner) return { ok: false, error: invalid };
  if (partner.status !== "ACTIVE") return { ok: false, error: CREATOR_CODE_MESSAGES.inactive };
  return { ok: true, code, partnerName: partner.name };
}

"use server";

import { placeHostingOrder } from "@/lib/actions-hosting";
import { orderEmailHosting } from "@/lib/actions-email-hosting";

/* Form adapters for the two products whose order functions are not FormData-shaped.
 *
 * `payAndDeploy`, `payAndDeployGame` and `purchaseDomain` all take
 * `(prev, formData)`, so the wizard posts hidden fields straight to them.
 * `orderHostingAccount` and `orderEmailHosting` take POSITIONAL arguments, so
 * they need something between the form and the function.
 *
 * THE RULE FOR EVERYTHING IN THIS FILE: it translates, it does not decide.
 * No pricing, no eligibility, no wallet arithmetic, no validation beyond
 * reading strings out of a FormData. Every one of those already lives inside
 * the real function — impersonation refusal, the email-verification gate, the
 * domain-uniqueness check, the wallet/card split — and a second copy here would
 * be a second set of rules guarding the same money, free to drift.
 *
 * Both exports are network-callable (`"use server"` makes every export so), and
 * both are spend paths. That is acceptable ONLY because each is a thin call into
 * a function that does its own authorisation. Do not add anything here that
 * authorises, prices, or charges on its own.
 */

export type SubmitState = { error?: string; ok?: boolean; checkout?: { clientSecret: string; publishableKey: string } };

/** Place a shared-hosting order from the wizard's form. */
export async function submitHosting(_prev: SubmitState, formData: FormData): Promise<SubmitState> {
  /* `placeHostingOrder`, NOT `orderHostingAccount`.
   *
   * They are not variants of one another. `orderHostingAccount` takes no
   * `useWallet` argument at all, so it ALWAYS spends the balance when the
   * balance covers the cost — which means it always places the order and never
   * yields a Stripe session. The wizard's "use account balance" toggle had
   * nowhere to send its value, the card fields could therefore never appear for
   * hosting, and calling it to obtain a session instead created a real account
   * every time (200 of them, in this sandbox, before it hit the node's cap).
   *
   * `placeHostingOrder` is the wallet-aware entry point: it honours the toggle,
   * returns `{ checkout }` when a card leg is due WITHOUT placing anything, and
   * only commits when the balance actually covers the total. Everything else —
   * pricing, the promo claim, the hostname claim, the impersonation and
   * email-verification gates — stays inside it. */
  const res = await placeHostingOrder({
    planId: String(formData.get("planId") ?? ""),
    domain: String(formData.get("domain") ?? "").trim() || undefined,
    subdomainLabel: String(formData.get("subdomainLabel") ?? "").trim() || undefined,
    termMonths: Number(formData.get("termMonths") ?? 1),
    extraDiskGB: Number(formData.get("extraDiskGB") ?? 0) || undefined,
    idempotencyKey: String(formData.get("idempotencyKey") ?? ""),
    /* Only an explicit "0" declines the balance, matching the action's own
       default rather than re-deciding it here. */
    useWallet: formData.get("useWallet") !== "0",
  });

  if ("error" in res) return { error: res.error };
  if ("needCard" in res) {
    return { error: "Add a payment card to your account first — this plan renews automatically." };
  }
  if ("checkout" in res) return { checkout: res.checkout };
  return { ok: true };
}

/** Place a business-email order from the wizard's form. */
export async function submitEmail(_prev: SubmitState, formData: FormData): Promise<SubmitState> {
  const domainName = String(formData.get("domain") ?? "").trim();
  const emailPlanId = String(formData.get("planId") ?? "");
  const termMonths = Number(formData.get("termMonths") ?? 1);
  // Defaults ON, and only an explicit "0" turns it off — matching the real
  // function's own default rather than re-deciding it here.
  const useWallet = formData.get("useWallet") !== "0";

  const res = await orderEmailHosting(domainName, emailPlanId, termMonths, useWallet);
  /* Error first: a result carrying BOTH would otherwise be reported as a
     checkout to mount rather than a problem to show. */
  if ("error" in res && res.error) return { error: res.error };
  if ("checkout" in res && res.checkout) return { checkout: res.checkout };
  return { ok: true };
}
"use server";

import { requireUser } from "@/lib/auth";
import { gameOrderQuote, type GameOrderIntent } from "@/lib/game-order";
import { couponAccountEligibilityError } from "@/lib/coupon-redemption";

/* Live pricing for the GAME path of the deploy wizard.
 *
 * Its own file for the same reason as lib/nx/quote.ts: `"use server"` makes
 * EVERY export in a module network-callable by anyone who can reach the app, so
 * a module that exposes pricing exposes exactly one function, it requires a
 * signed-in user, and it only reads. Do not add a second export here, and never
 * let anything that mutates share this file.
 *
 * The wizard shows a running total as the customer changes tier and term. That
 * total comes from `gameOrderQuote` — the same function `payAndDeployGame`
 * prices against — and never from arithmetic in the browser. A price the view
 * works out is a second pricing formula, and the moment the two disagree the
 * customer is shown one number and charged another.
 */

export type GameQuoted = {
  ok: true;
  chargeCents: number;
  monthlyCents: number;
  months: number;
  planName: string;
  gameFamily: string;
  /** Resolved server hostname, so the summary shows what will actually exist. */
  hostname: string;
  /** Minecraft only — `<subdomain>.play.nxeon.cloud`. Null for other families. */
  subdomain: string | null;
  variant: string;
  /** Percent off the regular term the tier's intro price represents — 0 when
   *  the tier has no intro price. Lets the wizard say "renews at $X/mo after
   *  your first term" without a second pricing formula in the browser. */
  introPercent: number;
  /** Mirrors lib/nx/quote.ts's QuotedPrice coupon fields exactly — see
   *  gameOrderQuote (lib/game-order.ts) for how these are computed. Added
   *  2026-09-22: this whole function used to drop `intent.couponCode` and
   *  hardcode these away entirely, so a coupon attached to a GAME order (the
   *  trial promo's default landing) never showed in the wizard's live total
   *  even though gameOrderQuote/payAndDeployGame already priced and charged
   *  it correctly — exactly the "shown one number, charged another" failure
   *  this file's own header comment warns about, just not the direction the
   *  warning was written for. */
  couponLabel: string | null;
  couponDiscountCents: number;
  couponError: string | null;
  /** What this order actually renews at, every cycle — see lib/game-order.ts's
   *  renewalTotalCents (mirrors lib/order.ts's VPS field of the same name). */
  renewalTotalCents: number;
  /** Creator Partner Program (2026-09-26) — see lib/nx/quote.ts's QuotedPrice
   *  identical fields for the full reasoning. 0 / "NONE" for the overwhelming
   *  majority never attached to an active partner. */
  partnerDiscountCents: number;
  partnerDiscountPercent: number;
  partnerDiscountTier: "FIRST" | "RECURRING" | "NONE";
  partnerName: string | null;
};

export type GameQuoteResult = GameQuoted | { ok: false; error: string };

/**
 * Price a game selection. Read-only.
 *
 * Errors are RETURNED rather than thrown: a half-made selection is the normal
 * state of a wizard, not an exception, and the cart should show nothing rather
 * than an error boundary.
 */
export async function quoteGameOrder(intent: GameOrderIntent): Promise<GameQuoteResult> {
  const user = await requireUser();
  try {
    const q = await gameOrderQuote(intent, { userId: user.id });
    // Catalog-level checks (service/plan/term/dates/global cap) already ran
    // inside gameOrderQuote; this adds the two ACCOUNT-level ones it can't see
    // — see couponAccountEligibilityError's own doc comment for why the
    // preview needs this too, not just the real reservation at pay time.
    let couponDiscountCents = q.couponDiscountCents ?? 0;
    let couponLabel: string | null = q.couponLabel || null;
    let couponError: string | null = q.couponError || null;
    if (q.couponId && couponDiscountCents > 0) {
      const ineligible = await couponAccountEligibilityError({
        userId: user.id,
        firstTimeOnly: q.couponFirstTimeOnly,
        excludeActiveCustomers: q.couponExcludeActiveCustomers,
      });
      if (ineligible) {
        couponDiscountCents = 0;
        couponLabel = null;
        couponError = ineligible;
      }
    }
    return {
      ok: true,
      // q.chargeCents already has q.couponDiscountCents subtracted once; add it
      // back to recover the full (undiscounted) price, then subtract whatever
      // the corrected (possibly now-zeroed) discount actually is.
      chargeCents: q.chargeCents + (q.couponDiscountCents ?? 0) - couponDiscountCents,
      monthlyCents: q.monthlyCents,
      months: q.term,
      planName: q.planName,
      gameFamily: q.gameFamily,
      hostname: q.hostname,
      subdomain: q.subdomain,
      variant: q.variant,
      introPercent: q.introPercent,
      couponLabel,
      couponDiscountCents,
      couponError,
      renewalTotalCents: q.renewalTotalCents ?? q.chargeCents,
      partnerDiscountCents: q.partnerDiscountCents ?? 0,
      partnerDiscountPercent: q.partnerDiscountPercent ?? 0,
      partnerDiscountTier: q.partnerDiscountTier ?? "NONE",
      partnerName: q.partnerName ?? null,
    };
  } catch (e) {
    // The real reason when it is one the customer can act on (an unsupported
    // term, a taken subdomain); never an internal message.
    return { ok: false, error: e instanceof Error ? e.message : "Couldn't price that selection." };
  }
}

    } catch {
      return null;
    }
  }
  if (!obj || typeof obj !== "object") return null;
  const { chargeCents } = obj as Record<string, unknown>;
  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
  return { chargeCents };
}

export type GameOrderQuote = {
  gamePlanId: string;
  gameFamily: string;
  planName: string;
  basePlanId: string;
  /** The base plan's RAM — fed to scheduleNode() to pick a node, same as VPS orders. */
  ramMB: number;
  osTemplateId: string;
  /** Normalised term (1 or 12). */
  term: number;
  /** Annual-discount rate resolved at quote time; frozen onto the Server at sale. */
  annualPct: number;
  /** DB-fed per-month base (priceCents / termMonths). */
  monthlyCents: number;
  /** The net charge for the whole term — displayed === charged === renewed. */
  chargeCents: number;
  /** The raw GamePlan.priceCents this order was placed against — the rate this server's renewal freezes to (grandfather program, Server.grandfatheredRenewalCents). NOT a term total. */
  gamePlanPriceCents: number;
  /** The regular (renewal-basis) term total, before intro/coupon discount. Display/coupon use only. */
  regularPlanCents: number;
  /** Percent off `regularPlanCents` the intro price represents — 0 for a plan with no intro price. Stamped on Server.termPromoPercent. */
  introPercent: number;
  hostname: string;
  label: string | null;
  variant: string;
  /** Minecraft only: the validated, available `<subdomain>.play.nxeon.cloud` label. Null for every other family. */
  subdomain: string | null;
  /** Whether the customer opted for a dedicated IPv4. */
  dedicatedIp: boolean;
  /** The dedicated-IP surcharge included in `chargeCents` (0 when not opted in). */
  ipCents: number;
  /** Clean, fully-populated gameplay values ready to persist (may be empty). */
  values: Record<string, string | number | boolean>;
  /** Verified coupon id to claim at placeGameOrder time, or null (no code / bad code). */
  couponId: string | null;
  /** The discount actually applied, in cents (0 when no valid code). */
  couponDiscountCents: number;
  /** Human label ("40% off (first 1 month)") for the wizard/preview. */
  couponLabel: string;
  /** Why the code didn't apply, for the wizard preview. Empty when it did (or none given). */
  couponError: string;
  couponMaxRedemptions: number | null;
  couponFirstTimeOnly: boolean;
  couponExcludeActiveCustomers: boolean;
  couponTrialDays: number | null;
  /** What this order actually renews at, every cycle — the plan (no coupon/intro
   *  discount, first-term-only) plus the recurring dedicated-IP line, discounted
   *  at this customer's RECURRING partner rate if attached. Mirrors lib/order.ts's
   *  renewalTotalCents. */
  renewalTotalCents: number;
  /** Creator Partner Program (2026-09-26) — see lib/order.ts orderQuote's own doc
   *  comment on the identical fields. 0 / "NONE" for the overwhelming majority. */
  partnerDiscountCents: number;
  partnerDiscountPercent: number;
  partnerDiscountTier: "FIRST" | "RECURRING" | "NONE";
  partnerName: string | null;
};

/**
 * Validate + price a game order without placing it. Throws GameOrderError on any
 * problem. Pure of side effects beyond reads. The price is the whole truth about
 * what this order costs; the caller (wallet split, review step, checkout stamp)
 * quotes from THIS so what the customer sees is what settles.
 */
export async function gameOrderQuote(
  intent: GameOrderIntent,
  opts?: {
    /**
     * CREATOR PARTNER PROGRAM (2026-09-26): see lib/order.ts orderQuote's own
     * doc comment on the identical option — same optional, additive, 0%-by-
     * default behavior. A game server is never a domain, so this always
     * resolves through the non-domain path.
     */
    userId?: string;
  },
): Promise<GameOrderQuote> {
  const term = normalizeProductTerm(intent.termMonths);

  const gp = await db.gamePlan.findUnique({
    where: { id: intent.gamePlanId },
    include: { basePlan: true },
  });
  // A ONE-OFF CUSTOM game tier (lib/custom-plan.ts createCustomGamePlan, "build a
  // custom server") and its backing base Plan are both deliberately created
  // `active: false` — see the matching comment on lib/order.ts orderQuote's own
  // gate for why (30+ untouched `where: { active: true }` catalog queries across
  // this codebase must never surface either row generically). `sortOrder` is the
  // marker reserved for exactly this row shape, accepted here as an alternative.
  if (!gp || (!gp.active && gp.sortOrder !== CUSTOM_PLAN_SORT_ORDER)) {
    throw new GameOrderError("That game plan isn't available.");
  }
  if (!gp.basePlan?.active && gp.basePlan?.sortOrder !== CUSTOM_PLAN_SORT_ORDER) {
    throw new GameOrderError("Provisioning is temporarily unavailable for this game.");
  }
  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
    throw new GameOrderError("Unknown game family.");
  }
  // DayZ's dedicated-server depot rejects anonymous SteamCMD login — every
  // order needs Nxeon's own dedicated Steam account (see lib/dayz-steam.ts).
  // Checked on every quote (not just at final order placement, unlike CS2's
  // GSLT auto-mint below, which is deliberately deferred to avoid burning
  // Valve's rate-limited account budget on live-preview keystrokes) because
  // this is a free, local boolean check with no external cost — so the
  // wizard can show an honest "not available yet" immediately rather than
  // only after checkout. Never let an order through that would just
  // crash-loop on SteamCMD's own login rejection.
  if (gp.gameFamily === "dayz" && !dayzSteamConfigured()) {
    throw new GameOrderError("DayZ hosting isn't available yet — check back soon, or contact support.");
  }

  // Resolve the game image: the tier's own OsTemplate, else any active image for
  // this family. A game server can't provision without an image.
  let osTemplateId = gp.osTemplateId;
  if (osTemplateId) {
    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
    if (!os?.active) osTemplateId = null;
  }
  if (!osTemplateId) {
    const os = await db.osTemplate.findFirst({
      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
      orderBy: { sortOrder: "asc" },
    });
    if (!os) throw new GameOrderError("No game image is configured for this game yet.");
    osTemplateId = os.id;
  }

  // Hostname: validate a provided one strictly, else auto-generate a safe one.
  const rawHost = (intent.hostname ?? "").trim().toLowerCase();
  let hostname = rawHost;
  if (hostname === "") {
    hostname = `${gp.gameFamily}-${randSuffix()}`;
  } else if (!(hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname))) {
    throw new GameOrderError(
      "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.",
    );
  }

  const label = (intent.serverName ?? "").trim().slice(0, 60) || null;

  // Per-game setup: variant + gameplay settings, validated against the family
  // schema. Families without a customization schema (e.g. Terraria) carry no
  // variant and no gameplay values — the wizard shows only identity fields for them.
  const schema = schemaFor(gp.gameFamily);
  let variant = "";
  let values: Record<string, string | number | boolean> = {};
  if (schema) {
    variant = (intent.variant ?? "").trim() || schema.defaultVariant;
    if (!isValidVariant(gp.gameFamily, variant)) {
      throw new GameOrderError("Choose a valid server type for this game.");
    }
    const res = validateConfig(gp.gameFamily, intent.config ?? {});
    if (!res.ok) throw new GameOrderError(res.error);
    values = res.values;
  }

  // A customer-chosen `<subdomain>.play.nxeon.cloud`, required at checkout
  // for every family with a real client-side hostname-connect story (see
  // lib/game-subdomain.ts — the free tier's own name rules, shared so the
  // two products can never disagree on what's valid or taken). Java
  // Minecraft gets a full A+SRV pair (players type only the subdomain);
  // Bedrock and everything in `HOSTNAME_CONNECT_FAMILIES` (lib/games.ts —
  // confirmed via real per-title research, not assumed) get an A record
  // only (players still type the port alongside it — none of them support
  // SRV) — worth less on its own, but still a memorable hostname instead of
  // a raw IP, and one that survives the underlying IP changing. Every other
  // family has no confirmed client-side hostname story, so this stays null
  // for them.
  let subdomain: string | null = null;
  if (gp.gameFamily === "minecraft" || gp.gameFamily === "bedrock" || HOSTNAME_CONNECT_FAMILIES.has(gp.gameFamily as GameFamily)) {
    const sub = (intent.subdomain ?? "").trim().toLowerCase();
    if (!sub) throw new GameOrderError("Pick a subdomain for your server — this is how players will connect.");
    const formatError = validateSubdomainFormat(sub);
    if (formatError) throw new GameOrderError(formatError);
    if (!(await isSubdomainAvailable(sub))) throw new GameOrderError("That subdomain is taken — try another.");
    subdomain = sub;
  }

  // Price: DB-fed base × term, annual discount resolved ONCE and frozen at sale.
  // Every seeded plan is `termMonths: 1`, so monthlyCents === priceCents; the
  // divisor keeps the maths correct if a multi-month base plan is ever configured.
  const annualPct = await annualDiscountPct();
  const monthlyCents = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
  const wantIp = !!intent.dedicatedIp;
  const ipCents = wantIp ? (await dedicatedIpMonthlyCents()) * term : 0;
  const planChargeCents = termPriceCents(monthlyCents, term, annualPct);
  // GRANDFATHER PROGRAM: GamePlan now carries the same introPriceCents/
  // introTermMonths columns Plan has always had (lib/intro-pricing.ts's
  // helpers are generic over any `{priceCents}` row, so this is the exact
  // same math VPS uses, not a second formula). A plan without an intro price
  // set (introMonthlyCents null) sees introDiscountCents === 0 and
  // introFirstTermPlanCents === planChargeCents — byte-for-byte the pre-intro
  // behavior, so every existing game plan is unaffected until an admin
  // actually sets one.
  const introMonthlyCents = planIntroMonthlyCents(gp);
  const introTermMonthsVal = planIntroTermMonths(gp);
  const introDiscountCents = introFirstTermDiscountCents(monthlyCents, introMonthlyCents, term, introTermMonthsVal, annualPct);
  const introFirstTermPlanCents = Math.max(0, planChargeCents - introDiscountCents);
  const introPercent = introSoldPercent(planChargeCents, introDiscountCents);

  // Optional checkout coupon: discounts the PLAN portion only (never the
  // dedicated-IP add-on), same shared math + same "never widen on a bad code"
  // discipline as lib/order.ts orderQuote's VPS coupon block. The atomic
  // redemption claim (count + per-user + per-IP guards) happens in
  // placeGameOrder, not here — this is read-only pricing.
  let couponId: string | null = null;
  let couponDiscountCents = 0;
  let couponLabel = "";
  let couponError = "";
  let couponMaxRedemptions: number | null = null;
  let couponFirstTimeOnly = false;
  let couponExcludeActiveCustomers = false;
  let couponTrialDays: number | null = null;
  const code = (intent.couponCode ?? "").trim().toUpperCase();
  if (code) {
    if (!(await getSettingBool("coupons_enabled", true))) {
      couponError = "Promo codes are currently disabled.";
    } else {
      const coupon = await db.coupon.findUnique({ where: { code } });
      if (!coupon) {
        couponError = "That code isn’t valid.";
      } else {
        const verdict = couponOrderDiscountCents(
          {
            kind: coupon.kind,
            value: coupon.value,
            serviceKind: coupon.serviceKind,
            planSlug: coupon.planSlug,
            maxTermMonths: coupon.maxTermMonths,
            active: coupon.active,
            expiresAt: coupon.expiresAt,
            maxRedemptions: coupon.maxRedemptions,
            timesRedeemed: coupon.timesRedeemed,
            minAmountCents: coupon.minAmountCents,
          },
          {
            serviceKind: "GAME",
            // Game plans have no slug of their own — coupon.planSlug is matched
            // against the game family instead, so "GAMESALE" can be scoped to
            // e.g. "valheim" the same way a VPS coupon locks to "starter".
            planSlug: gp.gameFamily,
            planMonthlyCents: monthlyCents,
            termMonths: term,
            // The intro-discounted first-term charge, not the full regular
            // total — a coupon stacks on top of whatever this term is
            // actually being sold at, exactly like lib/order.ts's VPS path.
            planChargeCents: introFirstTermPlanCents,
          },
          new Date(),
        );
        if (verdict.ok) {
          couponId = coupon.id;
          couponDiscountCents = verdict.discountCents;
          couponLabel = verdict.label;
          couponMaxRedemptions = coupon.maxRedemptions;
          couponFirstTimeOnly = coupon.firstTimeOnly;
          couponExcludeActiveCustomers = coupon.excludeActiveCustomers;
          couponTrialDays = coupon.trialDays;
        } else {
          couponError = verdict.error;
        }
      }
    }
  }

  const preDiscountChargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents;
  // CREATOR PARTNER PROGRAM — see lib/order.ts orderQuote's own doc comment on
  // the identical block; same math, same stacking order (on top of intro/coupon).
  const partnerDiscount = await partnerDiscountForNewOrder(opts?.userId);
  const partnerDiscountCents = partnerDiscountCentsFor(preDiscountChargeCents, partnerDiscount.percent);
  const chargeCents = preDiscountChargeCents - partnerDiscountCents;
  // Always the RECURRING (10%) tier for the "renews at" caption — see
  // lib/order.ts orderQuote's identical `partnerRenewalDiscount` comment.
  const partnerRenewalDiscount = await partnerDiscountForRenewal(opts?.userId);
  const renewalPreDiscountCents = planChargeCents + ipCents;
  const renewalTotalCents =
    renewalPreDiscountCents - partnerDiscountCentsFor(renewalPreDiscountCents, partnerRenewalDiscount.percent);

  return {
    gamePlanId: gp.id,
    gameFamily: gp.gameFamily,
    planName: gp.name,
    basePlanId: gp.basePlanId,
    ramMB: gp.basePlan.ramMB,
    osTemplateId,
    term,
    annualPct,
    monthlyCents,
    chargeCents,
    /**
     * The RAW GamePlan.priceCents this order was placed against — same units
     * `renewalCharge` divides by `gamePlan.termMonths` — NOT a term total.
     * This is what a server's grandfathered renewal rate freezes to; it is
     * deliberately not `regularPlanCents`/`chargeCents` below, which already
     * have this ORDER's term length and annual discount baked in and would
     * freeze the wrong (much larger, for a multi-month term) number.
     */
    gamePlanPriceCents: gp.priceCents,
    /** The regular (renewal-basis) term total, before any intro/coupon discount. Display/coupon use only — NOT the grandfather basis (see gamePlanPriceCents). */
    regularPlanCents: planChargeCents,
    /** Percent off the regular term the intro price represents — stamped on Server.termPromoPercent so proration prices against the rate this term was actually sold at. 0 when the plan has no intro price. */
    introPercent,
    hostname,
    label,
    variant,
    subdomain,
    dedicatedIp: wantIp,
    ipCents,
    values,
    couponId,
    couponDiscountCents,
    couponLabel,
    couponError,
    couponMaxRedemptions,
    couponFirstTimeOnly,
    couponExcludeActiveCustomers,
    couponTrialDays,
    renewalTotalCents,
    partnerDiscountCents,
    partnerDiscountPercent: partnerDiscount.percent,
    partnerDiscountTier: partnerDiscount.tier,
    partnerName: partnerDiscount.partner?.name ?? null,
  };
}

/**
 * Place a game order: re-validate + price, capacity-check, then atomically debit
 * the wallet and create the Server (sized by the tier's base VPS plan, running the
 * game image, with the customer's variant + gameplay settings) plus a PROVISION
 * job. Returns the new server id. Does NOT redirect.
 *
 * `sold` (card path) overrides the recomputed price with the one the order was

 * `sold` (card path) overrides the recomputed price with the one the order was
 * SOLD at — the card-paid path passes the figure stamped on the Checkout session
 * BEFORE the card was charged, so the confirm/webhook fulfilment settles the price
 * the customer consented to instead of re-pricing against a rate that changed in
 * between. The wallet path omits it and pays the fresh quote it computed moments
 * ago. This mirrors `sold` in lib/order.ts placeOrder.
 *
 * Callers must ensure funds exist (the card leg pre-credits the wallet, the wallet
 * path is gated by the balance check in the action). This still enforces the
 * balance and throws GameOrderError("Insufficient balance…") otherwise — no overdraft.
 */
export async function placeGameOrder(
  user: User,
  intent: GameOrderIntent,
  sold?: GameOrderPrice | null,
  /** CARD path only: the hold `payAndDeployGame` reserved before the card was
   *  charged (see reserveOrderCoupon), confirmed here — RESERVED→CONSUMED —
   *  inside the same tx that commits the order. Mirrors lib/order.ts
   *  placeOrder's `opts.couponReservationToken` exactly. */
  couponReservationToken?: string | null,
): Promise<string> {
  const quote = await gameOrderQuote(intent, { userId: user.id });

  // Resolve the ACTUAL hostname this server will get, now that the order is
  // really being placed (NOT inside gameOrderQuote, which the wizard calls on
  // every keystroke for a live price preview and has no business hitting the
  // DB or handing out a name it might never use). gameOrderQuote already
  // validated the format (or generated the "<family>-<rand>" default); this
  // only resolves UNIQUENESS, auto-suffixing on collision instead of letting
  // two customers' servers end up with the same hostname. See lib/hostname.ts.
  quote.hostname = await resolveUniqueHostname(quote.hostname, quote.gameFamily);

  // CS2 needs a Steam Game Server Login Token to register with matchmaking at
  // all (SRCDS_TOKEN, no longer a required checkout field as of 2026-09-17 —
  // see lib/game-config.ts's field comment). Mint one automatically, ONCE,
  // here at actual order placement — never in gameOrderQuote, which the
  // wizard calls on every keystroke for a live price preview and would burn
  // through Valve's 1000-account-per-key budget on customers who never buy.
  // A customer who pasted their own token is left alone; a Steam API hiccup
  // degrades to "no token yet" (server still deploys and runs, just isn't
  // listed on matchmaking until one is added from the dashboard) rather than
  // failing the whole paid order over it.
  if (quote.gameFamily === "cs2" && !quote.values.SRCDS_TOKEN && steamGsltConfigured()) {
    try {
      const account = await createGameServerAccount(730, `nxeon:${quote.hostname}`);
      quote.values.SRCDS_TOKEN = account.loginToken;
      quote.values._SRCDS_TOKEN_STEAMID = account.steamid;
