552	/**
553	 * The idempotent placement + post-order bookkeeping, WITHOUT the auth/pricing/split
554	 * preamble — takes the loaded `user` explicitly so BOTH the interactive action
555	 * (`placeHostingOrder`, wallet path) and the card-funded fulfilment path
556	 * (`fulfilCheckoutSession`) drive the SAME `hostorder:<key>` idempotency claim and the
557	 * SAME audited `orderHostingAccountFor` debit. On the card path the wallet was already
558	 * topped up by `creditCheckoutSession` before this runs.
559	 */
560	async function placeHostingOrderCore(
561	  user: User,
562	  input: HostingOrderInput,
563	  key: string,
564	  term: number,
565	  plan: { maxDatabases: number },
566	  extraGB: number,
567	  renewalCents: number,
568	  partnerSource?: string,
569	): Promise<HostingOrderResult> {
570	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
571	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
572	  // token table. A rapid resubmit or a network retry with the same key can't create
573	  // a second account or take a second debit.
574	  const sessionKey = `hostorder:${key}`;
575	  try {
576	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
577	  } catch (e) {
578	    if (isUniqueViolation(e)) {
579	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
580	      // A completed prior attempt: replay its result (no second charge).
581	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
582	      // A failed prior attempt: clear it so an explicit retry can proceed.
583	      if (prior?.status === "FAILED") {
584	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
585	      } else {
586	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
587	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
588	      }
589	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
590	      try {
591	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
592	      } catch {
593	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
594	      }
595	    } else {
596	      throw e;
597	    }
598	  }
599	
600	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
601	  // the free temporary subdomain. All money movement, the first-month-free atomic
602	  // claim and the hostname claim happen inside orderHostingAccountFor's transaction.
603	  const res = await orderHostingAccountFor(user, input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB, partnerSource);
604	  /* Only two outcomes are legitimate HERE. This runs AFTER the card cleared, so
605	     a `checkout` (another card leg) or `needCard` would mean the customer has
606	     paid and no account was opened — an anomaly worth recording as FAILED under
607	     its own wording rather than letting an unhandled branch fall through as
608	     success. `HostingOrderResult` is a union, so each branch has to be read
609	     explicitly; the old `HostingResult` had every field optional, which is what
610	     let `{ checkout }` pass silently as "no error, no accountId". */
611	  const failed = async (why: string) => {
612	    await db.fulfilledSession
613	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: why.slice(0, 500) } })
614	      .catch(() => {});
615	    return { error: why };
616	  };
617	  /* Narrowed one branch at a time so `res` itself is refined — after these
618	     three, it is the `{ ok: true; accountId: string }` member and `accountId`
619	     is known present. */
620	  if ("error" in res) return failed(res.error);
621	  if ("checkout" in res) return failed("The order still wanted a card payment after one had already cleared.");
622	  if ("needCard" in res) return failed("The order asked for a card to be added after one had already cleared.");
623	  if (!res.accountId) return failed("order failed");
624	  await db.fulfilledSession
625	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
626	    .catch(() => {});
627	
628	  // Deploy-funnel COMPLETION — hosting's authoritative, server-side bottom of the
629	  // funnel, the counterpart to placeOrder / placeGameOrder. Hosting does NOT flow
630	  // through the shared Stripe fulfilment bus (lib/fulfil-checkout.ts has no hosting
631	  // kind — a $0 first month captures a card in `mode:"setup"`, and the charge is the
632	  // wallet debit inside orderHostingAccount), so THIS is its shared success path.
633	  // Recorded here (not on the idempotent-replay early return above) so a retry never
634	  // double-counts. Replaces the client-side trackDeployComplete removed from
635	  // HostingDeployWizard, keeping all three products on one authoritative userId-keyed
636	  // completion. Best-effort + double-guarded so it can never disturb the placed order.
637	  try {
638	    await recordDeployFunnelComplete({ product: "hosting", step: "Complete", stepIndex: 7, userId: user.id });
639	  } catch {
640	    /* never let funnel bookkeeping affect a completed order */
641	  }
642	
643	  // Server-side Meta CAPI `Subscribe` — the free-month hosting signup is a browser-
644	  // ONLY conversion otherwise (HostingDeployWizard fires nxTrack('hosting') client-
645	  // side), so an ad blocker / privacy browser silently drops it and the campaign
646	  // never learns the signup happened. Firing it here too — with the SAME event_id
647	  // the browser pixel uses (idempotencyKey) — means Meta dedupes the two into ONE
648	  // conversion when the pixel DOES load, and still counts it when the pixel is
649	  // blocked. Value = the go-forward renewal (what optimisation should chase), NOT $0.
650	  // Best-effort: sendMetaConversion never throws, and this runs after the order is
651	  // already committed, so tracking can never affect the charge.
652	  try {
653	    const [h, ck] = await Promise.all([headers(), cookies()]);
654	    await sendMetaConversion({
655	      eventName: "Subscribe",
656	      eventId: key,
657	      email: user.email,
658	      externalId: user.id,
659	      value: renewalCents / 100,
660	      currency: "USD",
661	      clientIp: clientIp(h),
662	      userAgent: h.get("user-agent") ?? undefined,
663	      // The Meta click/browser cookies are the strongest match signals for an
664	      // ad-driven signup (an ad click sets _fbc). Passing them lifts Event Match
665	      // Quality well above the email/IP-only baseline. Absent for organic visits.
666	      fbc: ck.get("_fbc")?.value || undefined,
667	      fbp: ck.get("_fbp")?.value || undefined,
668	      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/dashboard/deploy` : undefined,
669	    });
670	  } catch {
671	    /* tracking is best-effort — the order is already placed and charged */
672	  }
673	
674	  // Optional one-click app install: queue it now so the worker installs it the
675	  // moment the account finishes provisioning. Best-effort — a bad slug never voids
676	  // the (already-charged) order; the customer can install from the panel later.
677	  const slug = String(input.appSlug ?? "").trim();
678	  if (slug) {
679	    try {
680	      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
681	    } catch {
682	      /* non-fatal: the account is created and charged; the app can be installed later */
683	    }
684	  }
685	
686	  revalidatePath("/dashboard/hosting");
687	  return { ok: true, accountId: res.accountId };
688	}
