690	/**
691	 * Fulfil a CARD-funded hosting order from its PAID Stripe session. Safe to expose as a
692	 * server action: it trusts NOTHING from its caller but a Stripe session id, which it
693	 * re-retrieves and re-classifies server-side — a forged or foreign id classifies as
694	 * anything-but-hostOrder and returns a no-op, so no one can place an order billed to
695	 * another account. Called ONLY by lib/fulfil-checkout.ts (the shared webhook+redirect
696	 * bus) AFTER it has credited the card leg to the wallet; this then runs the SAME
697	 * `placeHostingOrderCore` the wallet path uses (same `hostorder:<key>` idempotency),
698	 * so the wallet is debited exactly once and a webhook + redirect can never place two
699	 * accounts. `orderHostingAccountFor`'s own first-month-free atomic claim still decides
700	 * the final price here, exactly as on the wallet path.
701	 */
702	export async function placeHostingCardOrder(
703	  sessionId: string,
704	): Promise<HostingOrderResult | { skip: true }> {
705	  const purpose = await getCheckoutPurpose(sessionId);
706	  if (purpose.kind !== "hostOrder") return { skip: true };
707	  const user = await db.user.findUnique({ where: { id: purpose.userId } });
708	  if (!user) return { error: "user not found for paid hosting order" };
709	  const intent = purpose.intent;
710	  const term = normalizeProductTerm(intent.termMonths);
711	  const plan = await db.hostingPlan.findUnique({ where: { id: intent.planId } });
712	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
713	  const extraGB = normalizeExtraDiskAddGB(intent.extraDiskGB);
714	  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
715	  const input: HostingOrderInput = {
716	    planId: intent.planId,
717	    domain: intent.domain,
718	    subdomainLabel: intent.subdomainLabel,
719	    extraDiskGB: intent.extraDiskGB,
720	    termMonths: intent.termMonths,
721	    appSlug: intent.appSlug,
722	    idempotencyKey: intent.idempotencyKey,
723	    useWallet: true,
724	  };
725	  return placeHostingOrderCore(user, input, intent.idempotencyKey, term, plan, extraGB, renewalCents, intent.partnerSource);
726	}
