728	/**
729	 * Live availability check for a customer-chosen free subdomain (`<label>.<base>`).
730	 * Advisory UX for the deploy wizard — the authoritative de-dup is the atomic
731	 * UNIQUE(hostname) claim inside orderHostingAccount's charge tx, so a check that
732	 * says "available" can still lose a race and fail the order cleanly (no charge).
733	 */
734	export async function checkHostingSubdomain(
735	  labelRaw: string,
736	): Promise<{ available: boolean; fqdn: string; reason?: string }> {
737	  await requireUser();
738	  const label = String(labelRaw ?? "").trim().toLowerCase();
739	  const fqdn = freeSubdomainFor(label);
740	  if (!label) return { available: false, fqdn, reason: "Enter a subdomain." };
741	  if (!isValidSubdomainLabel(label)) {
742	    return { available: false, fqdn, reason: "Use 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
743	  }
744	  if (!isValidHostingDomain(fqdn)) {
745	    return { available: false, fqdn, reason: "That subdomain isn’t a valid hostname." };
746	  }
747	  if (await isHostnameClaimed(fqdn)) {
748	    return { available: false, fqdn, reason: "Already taken — try another." };
749	  }
750	  return { available: true, fqdn };
751	}
