180	 * has always set (a complete, immediately-priceable order with only free
181	 * defaults ticked), pulled out as a pure function so `orderFromIntent` below
182	 * can start from the identical baseline before layering a marketing button's
183	 * specific selections on top. Takes the PREVIOUS order as `base` only so
184	 * fields the picker doesn't own (nothing today) would survive a re-seed —
185	 * `chooseService` and `orderFromIntent` both currently pass a full record in.
186	 */
187	function seedOrder(base: Order, cat: Catalog, k: ServiceKey): Order {
188	  const rec = cat.plans.find((p) => p.recommended) ?? cat.plans[0];
189	  return {
190	    ...base,
191	    service: k,
192	    planId: k === "vps" ? rec?.id ?? null : null,
193	    // NOT `cat.regions[0]` — with no explicit `orderBy` on the `Node` query
194	    // this fed the wizard's picker, `regions[0]` was whatever order Postgres
195	    // happened to return rows in, so a fresh order could seed a random
196	    // region. `defaultRegionKey` is resolved server-side, deterministically
