199	    region: cat.defaultRegionKey ?? cat.regions[0]?.key ?? null,
200	    /* Must be a PLAIN_OS. Taking `oses[0]` picked whatever sorted first, and
201	       once the real catalogue landed that was Docker — an APPLICATION — so a
202	       fresh order defaulted to "operating system: Docker".
203	       Prefer the newest Ubuntu specifically — the most recognisable, most
204	       requested default — over whichever PLAIN_OS row happens to sort
205	       first alphabetically (AlmaLinux, before this). Falls back to the old
206	       "first PLAIN_OS" behavior if Ubuntu isn't in the catalogue at all. */
207	    osId: (
208	      cat.oses
209	        .filter((x) => x.category === "PLAIN_OS" && x.family === "ubuntu")
210	        .sort((a, b) => parseFloat(b.version || "0") - parseFloat(a.version || "0"))[0]
211	      ?? cat.oses.find((x) => x.category === "PLAIN_OS")
