274	/** The tier that best fits a desired headcount: the smallest slotted tier
275	 *  that still covers it, or — past the top of the ladder, or when the family
276	 *  has no slotted tiers at all — the single most expensive one, the closest
277	 *  real thing this family sells to "give me your biggest". Same judgment call
278	 *  GameLandingCombined's own player-count slider already makes, just applied
279	 *  against the LIVE catalogue instead of that page's illustrative fixture. */
280	function nearestTierBySlots(tiers: GameTier[], players: number): string | null {
281	  if (tiers.length === 0) return null;
282	  const slotted = tiers.filter((t): t is GameTier & { slots: number } => t.slots != null);
283	  const fits = slotted.filter((t) => t.slots >= players).sort((a, b) => a.slots - b.slots)[0];
284	  if (fits) return fits.id;
285	  const pool = slotted.length ? slotted : tiers;
286	  return [...pool].sort((a, b) => a.monthlyCents - b.monthlyCents).at(-1)?.id ?? null;
287	}
