289	/**
290	 * Materializes a `DeployIntent` into a real, catalogue-validated `Order` —
291	 * every id is checked against `cat` before it's used, so a stale or tampered
292	 * query string (an old link to a plan that's since been deactivated, say)
293	 * degrades to `seedOrder`'s normal defaults for whatever field didn't match,
294	 * never to a broken or half-filled order. Returns null when the URL carries
295	 * no recognised `product`, so the wizard opens on its ordinary empty first
296	 * step exactly as it always has.
297	 */
298	function orderFromIntent(cat: Catalog, intent: DeployIntent): Order | null {
299	  if (!intent.service) {
300	    // No specific service in the URL — but a coupon may still be attached
301	    // (a promo CTA that deliberately lands on the plain service picker
302	    // rather than defaulting into one product, e.g. lib/actions-promo-trial.ts's
303	    // ANY-service trial coupon — "works on any Game Server or Cloud VPS
304	    // plan" stops being true in practice if the button always drops the
305	    // customer into Game Servers specifically). Carry the coupon into the
306	    // ordinary empty first step instead of dropping it entirely.
307	    return intent.couponCode ? { ...EMPTY, couponCode: intent.couponCode } : null;
308	  }
309	  const o = seedOrder(EMPTY, cat, intent.service);
310	  // Applied regardless of which service branch runs below — a coupon covering
311	  // "any VPS or Game Server" (see lib/promo-trial.ts) isn't service-specific,
312	  // it just needs a real order to attach to.
313	  if (intent.couponCode) o.couponCode = intent.couponCode;
314	
315	  const term = intent.termMonths;
316	  if (term != null && cat.terms.some((t) => t.months === term)) o.termMonths = term;
317	
318	  // A region is not VPS-specific — game orders carry one too (`o.region`
319	  // gates the wizard's Region step for both). This used to live inside the
320	  // `vps`-only branch below, so a marketing page's "closest region" choice
321	  // (e.g. a game's own region picker, or `?region=fsn1` on a deploy link)
322	  // was read off the URL, matched against the real catalogue, and then
323	  // silently thrown away the moment `intent.service === "game"` — the
324	  // customer picked Germany on the marketing site and landed back on
325	  // whatever `seedOrder` defaulted to. Applied once, before the
326	  // per-service branches, so both paths get it.
327	  if (intent.region && cat.regions.some((r) => r.key === intent.region)) o.region = intent.region;
328	
329	  if (intent.service === "vps") {
330	    if (intent.planId && cat.plans.some((p) => p.id === intent.planId)) o.planId = intent.planId;
331	    if (intent.addons?.length) {
332	      const valid = new Set<string>(cat.addons.map((a) => a.key));
333	      const picked = intent.addons.filter((a) => valid.has(a));
334	      if (picked.length) o.addons = picked;
335	    }
336	    if (intent.diskGb != null && intent.diskGb >= 0) o.diskGb = Math.round(intent.diskGb);
337	  }
338	
339	  if (intent.service === "game") {
340	    const g = intent.gameFamily ? cat.games.find((x) => x.family === intent.gameFamily) : null;
341	    if (g) {
342	      o.gameFamily = g.family;
343	      const exact = intent.gamePlanId ? g.tiers.find((t) => t.id === intent.gamePlanId) : null;
344	      o.gamePlanId =
345	        exact?.id
346	        ?? (intent.players && intent.players > 0 ? nearestTierBySlots(g.tiers, intent.players) : null)
347	        ?? [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0]?.id
348	        ?? null;
349	      o.gameVariant =
350	        intent.gameVariant && g.variants.some((v) => v.id === intent.gameVariant)
351	          ? intent.gameVariant
352	          : g.defaultVariant;
353	    }
354	  }
355	
356	  if (intent.service === "hosting" && intent.hostingPlanId && cat.hosting.some((h) => h.id === intent.hostingPlanId)) {
357	    o.hostingPlanId = intent.hostingPlanId;
358	  }
359	
360	  if (intent.service === "email" && intent.emailPlanId && cat.email.some((e) => e.id === intent.emailPlanId)) {
361	    o.emailPlanId = intent.emailPlanId;
362	  }
363	
364	  return o;
365	}
