370	export function OrderProvider({ cat: baseCat, children }: { cat: Catalog; children: React.ReactNode }) {
371	  /* One-off custom plans built in THIS session. They are real (inactive,
372	     sortOrder 999) Plan/GamePlan rows the server just created, but they are not
373	     in the page's catalogue — so they are merged in here, and every lookup
374	     below (`plan`, `game.tiers`, the summary, the bottom bar) finds them
375	     exactly like a catalogue row. One custom build per product/family: a
376	     rebuild replaces the previous one rather than piling up cards. */
377	  const [customPlans, setCustomPlans] = useState<PlanOption[]>([]);
378	  const [customTiers, setCustomTiers] = useState<Record<string, GameTier[]>>({});
379	  const cat = useMemo<Catalog>(() => {
380	    if (customPlans.length === 0 && Object.keys(customTiers).length === 0) return baseCat;
381	    return {
382	      ...baseCat,
383	      plans: [...baseCat.plans, ...customPlans],
384	      games: baseCat.games.map((g) =>
385	        customTiers[g.family]?.length ? { ...g, tiers: [...g.tiers, ...customTiers[g.family]] } : g),
386	    };
387	  }, [baseCat, customPlans, customTiers]);
