/* ------------------------------------------------------------------ *
 * Business-email order — mirrors orderEmailHosting (no promo at all).
 * ------------------------------------------------------------------ */

export type EmailExternalInput = {
  domainName: string;
  emailPlanId: string;
  termMonths?: number;
  useWallet?: boolean;
};

const EMAIL_DOMAIN_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i;

async function quoteEmailOrderForExternalPayment(
  input: EmailExternalInput,
): Promise<{ error: string } | { cardCents: number; metadata: Record<string, string> }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  const name = String(input.domainName ?? "").trim().toLowerCase().replace(/\.$/, "");
  if (!name) return { error: "Enter a domain." };
  if (!EMAIL_DOMAIN_RE.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };

  const plan = await db.emailPlan.findUnique({ where: { id: input.emailPlanId } });
  if (!plan || !plan.active) return { error: "That email plan isn't available." };
  const term = normalizeProductTerm(input.termMonths);
  const { fullCharge } = await emailChargeCents(plan, term);
  const useWallet = input.useWallet !== false;
  const { cardCents } = walletSplit({ dueCents: fullCharge, balanceCents: user.balanceCents, useWallet });
  if (cardCents <= 0) {
    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
  }

  const dupe = await db.emailSubscription.findFirst({ where: { domainName: name, status: { not: "CANCELLED" } } });
  if (dupe) {
    return {
      error:
        dupe.userId === user.id
          ? "This domain already has an email subscription."
          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
    };
  }

  const metadata: Record<string, string> = {
    nxeonUserId: user.id,
    nxeonEmailOrder: packExternalPaymentMetadata("Email order intent", { domainName: name, emailPlanId: input.emailPlanId, termMonths: term }),
  };
  return { cardCents, metadata };
}

export async function createEmailOrderPayPalOrder(input: EmailExternalInput): Promise<CreatePayPalOrderResult> {
  const user = await requireUser();
  const quoted = await quoteEmailOrderForExternalPayment(input);
  if ("error" in quoted) return quoted;
  return openPayPal({ userId: user.id, kind: "emailOrder", amountCents: quoted.cardCents, metadata: quoted.metadata, description: "Nxeon business email order" });
}

export async function createEmailOrderCoinbaseCharge(input: EmailExternalInput): Promise<CreateCoinbaseChargeResult> {
  const user = await requireUser();
  const quoted = await quoteEmailOrderForExternalPayment(input);
