const HOSTING_HREF = "/dashboard/hosting";

/** Charge one hosting renewal, CAS-guarded on expiresAt (double-charge guard). */
async function chargeHostingRenewal(
  acct: { id: string; userId: string; primaryDomain: string; expiresAt: Date | null },
  planName: string,
  priceCents: number,
  newExpiry: Date,
): Promise<boolean> {
  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.hostingAccount.updateMany({
        where: { id: acct.id, status: "ACTIVE", expiresAt: acct.expiresAt },
        data: { expiresAt: newExpiry },
      });
      if (advanced.count === 0) throw new AlreadyHandledError(`hosting ${acct.id}`);
      if (priceCents > 0) {
        await debitWallet(tx, acct.userId, priceCents);
        await tx.walletTransaction.create({
          data: { userId: acct.userId, amountCents: -priceCents, description: `Web Hosting renewal: ${planName} for ${acct.primaryDomain}` },
        });
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: acct.userId,
            description: `Web Hosting renewal: ${planName} for ${acct.primaryDomain}`,
            status: "PAID",
            period: { start: acct.expiresAt, end: newExpiry },
            lineItems: [{ description: `${planName} — ${acct.primaryDomain}`, qty: 1, unitCents: priceCents, amountCents: priceCents }],
          }),
        });
      }
      await tx.auditLog.create({
        data: { userId: acct.userId, action: "billing.renewed", detail: `hosting ${acct.id} ${acct.primaryDomain} ${money(priceCents)} -> ${ymd(newExpiry)}` },
      });
      // First-month-free conversion: this is the SECOND term. Flip the redemption
      // anchored to this account to renewed (idempotent, same tx as the money).
      await markPromoRenewed(tx, acct.id);
    });
    return true;
  } catch (e) {
    if (e instanceof AlreadyHandledError) return false;
    if (e instanceof InsufficientBalanceError) return false;
    throw e;
  }
}

/** Suspend an unpaid hosting account past grace. Files are never deleted. */
async function suspendHosting(acct: { id: string; userId: string; primaryDomain: string; expiresAt: Date | null }) {
  const suspended = await db.hostingAccount.updateMany({
    where: { id: acct.id, status: "ACTIVE", expiresAt: acct.expiresAt },
    data: { status: "SUSPENDED", suspendedNote: "Payment overdue" },
  });
  if (suspended.count === 0) return;
  await db.auditLog.create({ data: { userId: acct.userId, action: "billing.suspended_unpaid", detail: `hosting ${acct.id} ${acct.primaryDomain}` } });
  await notify(acct.userId, `${acct.primaryDomain} hosting suspended — payment overdue`, `Top up your wallet and we'll restore it. Your files and databases are kept.`, HOSTING_HREF);
  console.log(`${LOG} suspended unpaid hosting account ${acct.id} (${acct.primaryDomain})`);
}

/**
 * When the wallet can't cover a hosting renewal but the customer has a saved card,
 * top the wallet up from the card for the shortfall — the SAME "card funds the
 * wallet, wallet pays the bill" model worker/billing.ts uses for VPS renewals, and
 * the answer to the checkout gate that accepts a card-on-file for a $0 first month.
 *
 * Reuses the audited off-session primitives verbatim: `chargeSavedCardOffSession`
 * (two idempotency guards — a permanent per-period marker + Stripe's 24h key) and
 * `creditOffSessionCharge` (UNIQUE(paymentIntentId) so a replay credits once). On
 * any failure the wallet is left untouched and the caller falls through to the
 * existing wallet-only grace/suspend path — a card wobble never suspends anyone
 * early. Returns the wallet balance to price the renewal decision against.
 */
async function topUpHostingFromCard(
  acct: { id: string; expiresAt: Date | null; primaryDomain: string; user: { id: string; email: string; name: string | null; balanceCents: number; stripeCustomerId: string | null; stripePaymentMethodId: string | null; cardBrand: string | null; cardLast4: string | null; cardExpMonth: number | null; cardExpYear: number | null } },
  priceCents: number,
): Promise<number> {
  const user = acct.user;
  if (canAfford(user.balanceCents, priceCents)) return user.balanceCents;
  if (!acct.expiresAt || !hasChargeableCard(user)) return user.balanceCents;
  // Wallet credit first, card for the remainder — identical split to checkout and
  // the VPS sweep, so the card is only ever asked for what the wallet can't cover.
  const split = walletSplit({ dueCents: priceCents, balanceCents: user.balanceCents, useWallet: true });
  if (split.cardCents <= 0) return user.balanceCents;
  const marker = renewalChargeMarker(acct.id, acct.expiresAt);
  const idempotencyKey = `nxeon_hostrenew_${acct.id}_${acct.expiresAt.getTime()}_${split.cardCents}`;
  const cardLabel = cardDisplayLabel({ brand: user.cardBrand, last4: user.cardLast4, expMonth: user.cardExpMonth, expYear: user.cardExpYear }) ?? "your saved card";
  const result = await chargeSavedCardOffSession({
    user,
    amountCents: split.cardCents,
    description: `Web Hosting renewal: ${acct.primaryDomain}`,
    marker,
    idempotencyKey,
    metadata: { nxeonHostingAccountId: acct.id, nxeonPeriodStart: acct.expiresAt.toISOString(), nxeonKind: "hosting_renewal" },
  });
  if (!result.ok) return user.balanceCents; // decline / 3DS / transient — fall through to grace
  // Credit the wallet with exactly what Stripe took (a replay credits once).
  await creditOffSessionCharge({
    userId: user.id,
    amountCents: result.amountCents,
    description: `Card payment for ${acct.primaryDomain} hosting renewal (${cardLabel})`,
    paymentIntentId: result.paymentIntentId,
  });
  return user.balanceCents + result.amountCents;
}

async function hostingDueSweep(now: Date) {
  const due = await db.hostingAccount.findMany({
    where: { status: "ACTIVE", expiresAt: { not: null, lt: now } },
    include: { plan: true, user: true },
  });
  const liveAnnual = await annualDiscountPct();
  const perGbCents = await extraDiskPerGbCents();
  for (const acct of due) {
    await step(`hosting renewal ${acct.id}`, async () => {
      if (!acct.expiresAt) return;
      const priceCents = hostingRenewalPrice(acct, liveAnnual, perGbCents);
      // Fund the wallet from a saved card if it's short (the wallet still pays the
      // renewal below). Best-effort — a failure leaves the wallet as-is.
      const balanceCents = await topUpHostingFromCard(acct, priceCents);
      const action = renewalDecision({ expiresAt: acct.expiresAt, now, autoRenew: true, balanceCents, priceCents });
      if (action === "renew") {
        // Advance by the account's own term, so an annual account renews annually.
        const newExpiry = nextExpiry(acct.expiresAt, now, subscriptionTermMonths(acct));
        const renewed = await chargeHostingRenewal(acct, acct.plan.name, priceCents, newExpiry);
        if (!renewed) return;
        await notify(acct.userId, `${acct.primaryDomain} hosting renewed`, `Charged ${money(priceCents)} for ${acct.plan.name}. Next renewal ${ymd(newExpiry)}.`, HOSTING_HREF);
        return;
      }
      if (action === "enforce") {
        await suspendHosting(acct);
        return;
      }
      await notifyOnce(
        now, acct.userId, acct.primaryDomain, "hosting renewal failed",
        `${acct.primaryDomain} hosting renewal failed — top up to keep it active`,
        `We couldn't charge ${money(priceCents)} (balance ${money(acct.user.balanceCents)}). Your site stays up until ${ymd(graceEndsAt(acct.expiresAt, PRODUCT_GRACE_DAYS))}, then it is suspended. Your files are not deleted.`,
        HOSTING_HREF,
      );
    });
  }
}

