export function partnerDiscountCentsFor(amountCents: number, percent: number): number {
  const clamped = Math.max(0, Math.min(100, percent));
  if (amountCents <= 0 || clamped <= 0) return 0;
  return Math.round((amountCents * clamped) / 100);
}

/**
 * Apply a resolved tier to an amount that is actually about to be charged, and
 * report the tier that EFFECTIVELY applied (2026-09-28, web hosting + business
 * email checkouts). The one difference from calling the two helpers above
 * separately: when the amount is $0 (a granted first-month-free hosting month)
 * nothing is discounted, so the effective tier is `NONE` — the charge must NOT
 * consume the customer's one-time 50% first-purchase slot (or show a "50% off"
 * line) for a purchase that saved them nothing. A $0 order is not a "paid
 * purchase" anywhere else in the program either: commission skips it
 * (partner-commission.ts `amountCents <= 0`) and so does the creator-code
 * first-purchase test (creator-code.ts `hasMadePaidPurchase`).
 */
export function applyPartnerDiscount(
  amountCents: number,
  tier: PartnerDiscountTier,
): { discountCents: number; netCents: number; tier: PartnerDiscountTier } {
  const discountCents = partnerDiscountCentsFor(amountCents, partnerDiscountPercentForTier(tier));
  return {
    discountCents,
    netCents: Math.max(0, amountCents) - discountCents,
    tier: discountCents > 0 ? tier : "NONE",
  };
}

