"use server";

import { cookies, headers } from "next/headers";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { normalizeProductTerm, termPriceCents } from "@/lib/billing-terms";
import { normalizeExtraDiskAddGB } from "@/lib/extra-disk";
import { hostingOrderDueCents } from "@/lib/hosting-pricing";
import { firstMonthFreeAppliesTo, firstMonthFreeEligible, firstMonthFreeEnabled } from "@/lib/promo-redemption";
import { partnerDiscountForRenewal } from "@/lib/partner-pricing";
import { partnerDiscountCentsFor } from "@/lib/partner-discount";
import { hashIp } from "@/lib/coupon-order";
import { clientIp } from "@/lib/rate-limit";

/* Live pricing for the WEB HOSTING path of the deploy wizard (2026-09-28).
 *
 * Its own file for the same reason as lib/nx/quote.ts and lib/nx/quote-game.ts:
 * `"use server"` makes EVERY export network-callable, so a module that exposes
 * pricing exposes exactly one function, requires a signed-in user, and only
 * reads. Do not add a second export here.
 *
 * Until this existed the wizard priced hosting in the browser from a flat
 * per-plan matrix the page handed down. That matrix cannot know anything about
 * THIS customer, so when the Creator Partner Program discount was added to the
 * hosting charge, the matrix would have shown one number and the order charged
 * another. This returns `hostingOrderDueCents` — the exact function
 * placeHostingOrder splits on and orderHostingAccountFor debits — so the total
 * shown is the total charged, first-month-free and partner discount included.
 */

export type HostingQuoted = {
  ok: true;
  /** What is due today — the figure the order will charge. */
  totalCents: number;
  months: number;
  /** The full, undiscounted term total (plan + storage). */
  regularPlanCents: number;
  /** First-month-free credit actually applied to this quote (0 when not eligible). */
  promoCreditCents: number;
  promoName: string;
  /** Web hosting has no coupon support (coupons are VPS / game only — see
   *  lib/coupon-order.ts OrderContext); a typed code is answered honestly here
   *  rather than silently ignored. */
  couponError: string | null;
  /** What this account renews at each cycle, at the RECURRING partner rate if attached. */
  renewalTotalCents: number;
  partnerDiscountCents: number;
  partnerDiscountPercent: number;
  partnerDiscountTier: "FIRST" | "RECURRING" | "NONE";
  partnerName: string | null;
};

export type HostingQuoteResult = HostingQuoted | { ok: false; error: string };

export async function quoteHostingOrder(input: {
  planId: string;
  termMonths?: number;
  extraDiskGB?: number;
  couponCode?: string;
}): Promise<HostingQuoteResult> {
  const user = await requireUser();
  try {
    const plan = await db.hostingPlan.findUnique({ where: { id: String(input.planId ?? "") } });
    if (!plan || !plan.active) return { ok: false, error: "That hosting plan isn’t available." };
    const term = normalizeProductTerm(input.termMonths);
    const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
    // The same eligibility inputs the order path resolves (account + IP hash).
    void cookies; // (no cookie input affects price — the campaign tag is attribution only)
    const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
    const eligible =
      firstMonthFreeAppliesTo("HOSTING") &&
      (await firstMonthFreeEnabled()) &&
      (await firstMonthFreeEligible(user.id, ipHash));
    const q = await hostingOrderDueCents(plan, term, extraGB, { userId: user.id, firstMonthFreeEligible: eligible });

    // Renews at the full term price (+ storage) — worker/product-renewals.ts's
    // hostingRenewalPrice for a fresh account — less the RECURRING partner rate
    // the renewal sweep applies.
    const renewalBase = termPriceCents(plan.priceCents, term, q.annualPct) + q.extraTermCents;
    const renewalPartner = await partnerDiscountForRenewal(user.id);
    const renewalTotalCents = renewalBase - partnerDiscountCentsFor(renewalBase, renewalPartner.percent);

    const promoCreditCents = q.fullCharge - q.preDiscountCents;
    const code = String(input.couponCode ?? "").trim();
    return {
      ok: true,
      totalCents: q.dueCents,
      months: term,
      regularPlanCents: q.fullCharge,
      promoCreditCents,
      promoName: promoCreditCents > 0 ? "First month free" : "",
      couponError: code ? "Promo codes apply to Cloud VPS and Game Server orders only." : null,
      renewalTotalCents,
      partnerDiscountCents: q.partnerDiscountCents,
      partnerDiscountPercent: q.partnerDiscountCents > 0 ? q.partner.percent : 0,
      partnerDiscountTier: q.partnerDiscountTier,
      partnerName: q.partnerDiscountCents > 0 ? q.partner.partner?.name ?? null : null,
    };
  } catch {
    return { ok: false, error: "Couldn't price that selection." };
  }
}

