    // the renewal sweep applies.
    const renewalBase = termPriceCents(plan.priceCents, term, q.annualPct) + q.extraTermCents;
    const renewalPartner = await partnerDiscountForRenewal(user.id);
    const renewalTotalCents = renewalBase - partnerDiscountCentsFor(renewalBase, renewalPartner.percent);

    const promoCreditCents = q.fullCharge - q.preDiscountCents;
    const code = String(input.couponCode ?? "").trim();
    return {
      ok: true,
      totalCents: q.dueCents,
      months: term,
      regularPlanCents: q.fullCharge,
      promoCreditCents,
      promoName: promoCreditCents > 0 ? "First month free" : "",
      couponError: code ? "Promo codes apply to Cloud VPS and Game Server orders only." : null,
      renewalTotalCents,
      partnerDiscountCents: q.partnerDiscountCents,
      partnerDiscountPercent: q.partnerDiscountCents > 0 ? q.partner.percent : 0,
      partnerDiscountTier: q.partnerDiscountTier,
      partnerName: q.partnerDiscountCents > 0 ? q.partner.partner?.name ?? null : null,
    };
  } catch {
    return { ok: false, error: "Couldn't price that selection." };
  }
}

