"use server";

import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { normalizeProductTerm } from "@/lib/billing-terms";
import { emailOrderDueCents } from "@/lib/email-pricing";
import { emailMonthlyBaseCents, productTermRenewalCents } from "@/lib/product-billing";
import { partnerDiscountForRenewal } from "@/lib/partner-pricing";
import { partnerDiscountCentsFor } from "@/lib/partner-discount";

/* Live pricing for the BUSINESS EMAIL path of the deploy wizard (2026-09-28).
 *
 * One export, signed-in only, read-only — the same rules as lib/nx/quote.ts,
 * lib/nx/quote-game.ts and lib/nx/quote-hosting.ts, for the same reason
 * (`"use server"` makes every export network-callable).
 *
 * Replaces the browser-side lookup into a flat per-plan matrix, which could not
 * know about THIS customer's Creator Partner Program discount. Returns
 * `emailOrderDueCents` — the exact function orderEmailHosting splits on and
 * orderEmailHostingCore debits — so the total shown is the total charged.
 */

export type EmailQuoted = {
  ok: true;
  totalCents: number;
  months: number;
  regularPlanCents: number;
  /** Business email has no coupon support (coupons are VPS / game only). */
  couponError: string | null;
  renewalTotalCents: number;
  partnerDiscountCents: number;
  partnerDiscountPercent: number;
  partnerDiscountTier: "FIRST" | "RECURRING" | "NONE";
  partnerName: string | null;
};

export type EmailQuoteResult = EmailQuoted | { ok: false; error: string };

export async function quoteEmailOrder(input: {
  emailPlanId: string;
  termMonths?: number;
  couponCode?: string;
}): Promise<EmailQuoteResult> {
  const user = await requireUser();
  try {
    const plan = await db.emailPlan.findUnique({ where: { id: String(input.emailPlanId ?? "") } });
    if (!plan || !plan.active) return { ok: false, error: "That email plan isn't available." };
    const term = normalizeProductTerm(input.termMonths);
    const q = await emailOrderDueCents(plan, term, { userId: user.id });
    // Renews at worker/product-renewals.ts's emailRenewalPrice for the
    // subscription this order would create (its term, the annual rate frozen at
    // sale), less the RECURRING partner rate the renewal sweep applies.
    const renewalBase = productTermRenewalCents(emailMonthlyBaseCents(plan), term, q.annualPct);
    const renewalPartner = await partnerDiscountForRenewal(user.id);
    const code = String(input.couponCode ?? "").trim();
    return {
      ok: true,
      totalCents: q.dueCents,
      months: term,
      regularPlanCents: q.fullCharge,
      couponError: code ? "Promo codes apply to Cloud VPS and Game Server orders only." : null,
      renewalTotalCents: renewalBase - partnerDiscountCentsFor(renewalBase, renewalPartner.percent),
      partnerDiscountCents: q.partnerDiscountCents,
      partnerDiscountPercent: q.partnerDiscountCents > 0 ? q.partner.percent : 0,
      partnerDiscountTier: q.partnerDiscountTier,
      partnerName: q.partnerDiscountCents > 0 ? q.partner.partner?.name ?? null : null,
    };
  } catch {
    return { ok: false, error: "Couldn't price that selection." };
  }
}

