import { test } from "node:test";
import assert from "node:assert/strict";
import {
  partnerDiscountTier,
  partnerDiscountPercentForTier,
  partnerDiscountPercent,
  partnerDiscountCentsFor,
  PARTNER_FIRST_PURCHASE_PCT,
  PARTNER_RECURRING_PCT,
} from "../lib/partner-discount.ts";
import { commissionableBaseCents } from "../lib/partner-commission.ts";
import { renewalCharge, type PricedServer, type RenewalPrices } from "../lib/renewal-charge.ts";

/**
 * Creator Partner Program — money-correctness tests, mirroring the shape of
 * test/retention-offer.test.ts and test/coupon-order.test.ts: pure arithmetic
 * asserted directly, no DB, no mocking.
 *
 * Three things under test:
 *  (a) the customer-facing discount tier/percent resolution (50% first
 *      purchase / 10% recurring / 0% not attached or domain), and the pure
 *      cents math that applies it.
 *  (b) the commission dedicated-IP exclusion rule: a partner earns 0% on a
 *      dedicated-IP add-on line, 100% of their normal rate on every other line
 *      in the same order/renewal.
 *  (c) both discounts wired into the ONE renewal formula (renewalCharge),
 *      stacking correctly with the pre-existing one-time retention offer.
 */

/* ------------------------------------------------------------------ *
145:test("renewalCharge: a partner-attached customer's renewal is 10% off, on the WHOLE renewal including the dedicated IP", () => {
156:test("renewalCharge: the retention offer and the partner discount STACK — retention first, partner discount on what's left", () => {
168:test("renewalCharge: partner discount is applied BEFORE tax, like every other discount on this platform", () => {
176:test("renewalCharge: a corrupt/out-of-range partnerDiscountPercent is clamped, same discipline as the retention percent", () => {
183:test("renewalCharge: a game server's dedicated IP is also broken out into ipCents for the commission exclusion", () => {
194 test/partner-discount.test.ts

