s=s.replace('''  partnerDiscountCentsFor,
  PARTNER_FIRST_PURCHASE_PCT,''','''  partnerDiscountCentsFor,
  applyPartnerDiscount,
  partnerDiscountLineLabel,
  PARTNER_FIRST_PURCHASE_PCT,''',1)
s += '''
/* ------------------------------------------------------------------ *
 * (d) applyPartnerDiscount — the web hosting / business email checkouts
 *     (2026-09-28). Same math as the VPS/game path, plus: a $0 charge (a
 *     granted first-month-free hosting month) discounts nothing and must NOT
 *     report the FIRST tier, so the one-time 50% slot is never spent on it.
 * ------------------------------------------------------------------ */

test("applyPartnerDiscount: FIRST tier takes 50% off and reports FIRST", () => {
  assert.deepEqual(applyPartnerDiscount(1999, "FIRST"), { discountCents: 1000, netCents: 999, tier: "FIRST" });
});

test("applyPartnerDiscount: RECURRING tier takes 10% off", () => {
  assert.deepEqual(applyPartnerDiscount(12000, "RECURRING"), { discountCents: 1200, netCents: 10800, tier: "RECURRING" });
});

test("applyPartnerDiscount: not attached (NONE) leaves the charge untouched", () => {
  assert.deepEqual(applyPartnerDiscount(12000, "NONE"), { discountCents: 0, netCents: 12000, tier: "NONE" });
});

test("applyPartnerDiscount: a $0 first-month-free hosting order does not spend the FIRST slot", () => {
  assert.deepEqual(applyPartnerDiscount(0, "FIRST"), { discountCents: 0, netCents: 0, tier: "NONE" });
});

test("applyPartnerDiscount: net + discount always equals the amount (invoice lines sum to the charge)", () => {
  for (const amount of [1, 3, 99, 101, 499, 1999, 12345, 999999]) {
    for (const tier of ["FIRST", "RECURRING", "NONE"] as const) {
      const r = applyPartnerDiscount(amount, tier);
      assert.equal(r.netCents + r.discountCents, amount, `${amount} ${tier}`);
      assert.ok(r.netCents >= 0);
    }
  }
});

test("partnerDiscountLineLabel: the invoice wording VPS/game already use", () => {
  assert.equal(partnerDiscountLineLabel("FIRST"), "Partner discount — 50% off your first purchase");
  assert.equal(partnerDiscountLineLabel("RECURRING"), "Partner discount — 10% off");
});
'''
