page.on("request", (r) => {
  if (r.method() === "POST" && r.headers()["next-action"]) {
    const body = r.postData() || "";
    posts.push(body.slice(0, 4000));
  }
});
await page.goto(BASE + path);
await page.waitForLoadState("domcontentloaded");
await page.waitForTimeout(4000);
for (const t of ["Skip", "No thanks, I’ll pay full price"]) {
  const b = page.locator(`button:has-text("${t}")`).first();
  if (await b.isVisible().catch(() => false)) { await b.click().catch(() => {}); await page.waitForTimeout(800); }
}
if (extra === "domain") {
  const inp = page.locator('input[placeholder*="domain" i], input[placeholder*=".com" i]').first();
  if (await inp.isVisible().catch(() => false)) { await inp.fill(`cf${Date.now()}.example.com`); await page.waitForTimeout(800); }
}
if (extra && extra.startsWith("coupon=")) {
  // typed into the Payment step's promo box below
}
// Jump to the Payment step via the rail.
const pay = page.locator('text=/^\\s*\\d?\\s*Payment\\s*$/').first();
await pay.click({ timeout: 5000 }).catch((e) => console.log("rail click failed", e.message));
await page.waitForTimeout(2500);
if (extra && extra.startsWith("coupon=")) {
  const box = page.locator('input[aria-label="Promo or creator code"]:visible').first();
  await box.fill(extra.slice(7));
  await page.waitForTimeout(3500);
}
await page.waitForTimeout(3000);
await page.screenshot({ path: shot });
const txt = await page.evaluate(() => document.body.innerText);
const lines = txt.split("\n").map((s) => s.trim()).filter((s) => /partner|discount|coupon|promo|STAY|off|Left to pay|Pay |due|renew|Then|%|valid|apply/i.test(s));
console.log([...new Set(lines)].slice(0, 40).join("\n"));
writeFileSync(`${shot}.posts.txt`, posts.join("\n-----\n"));
console.log("server-action POSTs:", posts.length);
await browser.close();
EOF
