import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
const BASE = "https://staging.nxeon.cloud";
// usage: node pay.mjs <stateTag> <path> <prep: hosting|email|game|none> <shotPrefix> [codes comma-separated]
const [tag, path, prep, shot, codes] = process.argv.slice(2);
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 1100 }, storageState: `state-${tag}.json`, locale: "en-US" });
const page = await ctx.newPage();
page.on("console", (m) => { if (m.type() === "error") console.log("[console]", m.text().slice(0, 200)); });
const dismiss = async () => { for (const t of ["Skip", "No thanks, I’ll pay full price", "Got it"]) { const b = page.locator(`button:has-text("${t}")`).first(); if (await b.isVisible().catch(() => false)) { await b.click().catch(() => {}); await page.waitForTimeout(500); } } };
await page.goto(BASE + path); await page.waitForTimeout(5000); await dismiss();
if (prep === "hosting") await page.locator('input[placeholder="mysite"]:visible').first().fill(`cf${Date.now().toString(36)}`);
if (prep === "email") await page.locator('input[placeholder="yourcompany.com"]:visible').first().fill(`cf${Date.now().toString(36)}.example.com`);
await page.waitForTimeout(1500);
await page.locator('text=/^\\s*\\d?\\s*Payment\\s*$/').first().click();
await page.waitForTimeout(3000); await dismiss();
const box = page.locator('input[aria-label="Promo or creator code"]:visible').first();
for (const c of (codes || "").split(",").filter(Boolean)) {
  await box.fill(c); await page.waitForTimeout(3500);
  const ap = page.locator('button:has-text("Apply creator code")');
  if (await ap.isVisible().catch(() => false)) { await ap.click(); await page.waitForTimeout(4000); }
}
await page.waitForTimeout(8000); await dismiss();
const summaryText = async () => {
  const txt = await page.evaluate(() => document.body.innerText);
  return [...new Set(txt.split("\n").map((s) => s.trim()).filter((s) => /partner discount|% off|Left to pay|^S?\$|Pay S?\$|Subtotal|First month|STAY/i.test(s)))].slice(0, 25).join(" | ");
};
await page.locator("text=Order summary").first().scrollIntoViewIfNeeded().catch(() => {});
await page.screenshot({ path: `${shot}-1-quote.png` });
console.log("QUOTE:", await summaryText());
const frame = page.frames().find((f) => /elements-inner-payment/.test(f.url()));
if (!frame) { console.log("NO CARD FRAME"); await browser.close(); process.exit(1); }
await frame.fill('input[name="number"]', "4242424242424242");
await frame.fill('input[name="expiry"]', "12 / 34");
await frame.fill('input[name="cvc"]', "123");
const name = await frame.$('input[name="linkLegalName"]'); if (name && await name.isVisible()) await name.fill("Checkout Fix Test").catch(() => {});
await page.waitForTimeout(2000);
const payBtn = page.locator('form button.btn-deploy').first();
console.log("pay button:", (await payBtn.innerText()).replace(/\s+/g, " "));
await payBtn.click();
for (let i = 0; i < 40; i++) {
  await page.waitForTimeout(1500);
  if (!/\/dashboard\/deploy/.test(page.url())) break;
  const t = await page.evaluate(() => document.body.innerText);
  if (/deploying|is live|provisioning|order placed|thank|success/i.test(t) && i > 6) break;
}
await page.waitForTimeout(4000);
console.log("AFTER URL:", page.url());
await page.screenshot({ path: `${shot}-2-after.png` });
const err = await page.evaluate(() => [...document.querySelectorAll(".text-rose")].map((e) => e.innerText).join(" | "));
if (err) console.log("ERRORS:", err);
await browser.close();
EOF
