/**
 * Checkout-coupon redemption — the RESERVATION lifecycle for the card/Stripe path.
 *
 * This mirrors lib/promo-redemption.ts's hold lifecycle (reserve → confirm → release
 * + a worker sweep + self-heal), applied to `CouponRedemption`. The wallet-atomic
 * grant still lives in lib/order.ts `claimOrderCoupon` and is unchanged; this module
 * is the machinery the CARD path needs so it never settles a discounted price up
 * front without an EXCLUSIVE hold behind it.
 *
 * WHY A COUPON IS HARDER THAN THE PROMO. The first-month-free promo is capped ONLY by
 * two unique constraints (1/account + 1/IP), so its reserve is a single guarded
 * INSERT. A coupon carries those two uniques AND a CONFIGURABLE global cap
 * (`Coupon.timesRedeemed` vs `maxRedemptions`). So a hold must ALSO occupy a slot in
 * that counter: reserve does the atomic conditional increment (the same one
 * `claimOrderCoupon` does), and release/self-heal/sweep DECREMENT it in lockstep when
 * a dead hold is deleted — otherwise an abandoned checkout would permanently burn a
 * global slot. A CONSUMED grant is never deleted here, so its increment stands.
 *
 * WHY A TYPED VIEW instead of `db.couponRedemption` directly: identical to
 * lib/promo-redemption.ts — the Prisma client in this tree is symlinked from prod and
 * regenerated only at deploy, so its types do not yet know the new reservation columns
 * (`state`, `reservedUntil`, `reservationToken`). Every raw-delegate access is
 * contained HERE behind `redemptionDelegate(...)`; when the client is regenerated the
 * runtime is identical and only these casts become redundant. (The `coupon` delegate is
 * already in the generated client, so `timesRedeemed` moves through the normal typed
 * client with no cast.)
 */

import { randomUUID } from "crypto";
import { Prisma } from "@prisma/client";
import { db } from "./db";

/**
 * Redemption row lifecycle. A wallet-atomic order inserts a CONSUMED grant in one step
 * (default state); the card/Stripe order first inserts a RESERVED hold (before the card
 * is charged) and later confirms it to CONSUMED. Both states physically occupy the two
 * unique slots AND a `timesRedeemed` slot, so a live hold blocks a second claim and
 * counts against the global cap exactly like a grant.
 */
export const COUPON_STATE = { RESERVED: "RESERVED", CONSUMED: "CONSUMED" } as const;
export type CouponState = (typeof COUPON_STATE)[keyof typeof COUPON_STATE];

/** A minimal, honestly-typed shape of the row we read back. */
export type CouponRedemptionRow = {
  id: string;
  couponId: string;
  userId: string;
  ipHash: string | null;
  amountCents: number;
  context: string;
  state: string;
  reservedUntil: Date | null;
  reservationToken: string | null;
  createdAt: Date;
};

type CouponRedemptionWhere = {
  couponId?: string;
  userId?: string;
  ipHash?: string;
  state?: string;
  reservationToken?: string;
  reservedUntil?: { lt: Date };
};

/** The subset of the CouponRedemption delegate this module uses, hand-typed. */
type CouponRedemptionDelegate = {
  create(args: {
    data: {
      couponId: string;
      userId: string;
      ipHash: string | null;
      amountCents: number;
      context?: string;
      state?: string;
      reservedUntil?: Date | null;
      reservationToken?: string | null;
    };
    select?: { id: true };
  }): Promise<{ id: string }>;
  findFirst(args: {
    where: CouponRedemptionWhere;
    select?: { id: true; couponId?: true };
  }): Promise<{ id: string; couponId: string } | null>;
  findMany(args?: {
    where?: CouponRedemptionWhere;
    take?: number;
  }): Promise<CouponRedemptionRow[]>;
  updateMany(args: {
    where: CouponRedemptionWhere;
    data: { state?: string; reservedUntil?: Date | null };
  }): Promise<{ count: number }>;
  deleteMany(args: { where: CouponRedemptionWhere }): Promise<{ count: number }>;
};

/** Anything that carries a `couponRedemption` (and `coupon`) delegate. */
type CouponClient = Prisma.TransactionClient | typeof db;

/** The one place the stale-client cast lives (new reservation columns only). */
function redemptionDelegate(client: CouponClient): CouponRedemptionDelegate {
  return (client as unknown as { couponRedemption: CouponRedemptionDelegate }).couponRedemption;
}

/**
 * Delete THIS claimant's own DEAD holds on a coupon — RESERVED rows whose `reservedUntil`
 * has passed and which were never confirmed (an abandoned/expired card checkout) — and
 * hand back the global slots they held (`timesRedeemed` decrement, one per deleted row).
 *
 * Strictly guarded — `state: RESERVED` AND `reservedUntil < now` — so a CONSUMED grant or
 * a still-live hold is NEVER touched, and the decrement can only ever undo an increment a
 * reserve made. This is the guarantee that an abandoned checkout can NEVER permanently
 * burn a customer's eligibility (per-person) or a coupon's last global slot: the very
 * next reserve/claim sweeps its own stale hold before contending. Runs inside the caller's
 * tx so the delete + decrement commit atomically. IP holds are cleared for the shared IP
 * slot too (a dead hold should block nobody).
 */
export async function releaseExpiredCouponHoldsFor(
  client: CouponClient,
  couponId: string,
  userId: string,
  ipHash: string | null,
): Promise<void> {
  const now = new Date();
  const d = redemptionDelegate(client);
  const delUser = await d.deleteMany({
    where: { couponId, state: COUPON_STATE.RESERVED, reservedUntil: { lt: now }, userId },
  });
  if (delUser.count > 0) {
    await client.coupon.update({ where: { id: couponId }, data: { timesRedeemed: { decrement: delUser.count } } });
  }
  if (ipHash) {
    const delIp = await d.deleteMany({
      where: { couponId, state: COUPON_STATE.RESERVED, reservedUntil: { lt: now }, ipHash },
    });
    if (delIp.count > 0) {
      await client.coupon.update({ where: { id: couponId }, data: { timesRedeemed: { decrement: delIp.count } } });
    }
  }
}

export type CouponReserveResult = { reserved: true; token: string } | { reserved: false; error: string };

/**
 * THE CARD/STRIPE HOLD. Insert a RESERVED redemption BEFORE the card is charged, so a
 * second concurrent checkout can't also pass the per-person AND global caps and walk away
 * with a second discount. Runs in ONE transaction that:
 *   1. self-heals this claimant's own dead holds (so an earlier abandonment never blocks);
 *   2. enforces first-time-only (no prior paid server);
 *   3. does the atomic conditional `timesRedeemed` increment — the ONE thing between the
 *      last global slot and an over-redemption when N checkouts race for it;
 *   4. inserts the RESERVED row (P2002 on the two uniques => this account/IP already holds
 *      or redeemed) — which rolls the whole tx (increment included) back.
 * So exactly one of N racing checkouts holds the slot; losers get `{ reserved: false }` and
 * the caller re-quotes at FULL price (displayed === charged). The returned `token` is
 * stamped into the Checkout session metadata and is what confirm/release target.
 */
/**
 * Read-only peek at the two ACCOUNT-level eligibility rules `reserveOrderCoupon`
 * (and `claimOrderCoupon`, lib/order.ts) enforce for real — `firstTimeOnly` and
 * `excludeActiveCustomers` — without taking a hold or touching the redemption
 * cap. Returns the same error string the real reservation would, or null when
 * eligible.
 *
 * For the live wizard PREVIEW only: `gameOrderQuote`/`orderQuote` compute the
 * discount from purely catalog-level facts (service/plan/term/dates/global cap)
 * with no account context, so an EXCLUDED customer used to see the discounted
 * price the entire way through the wizard — right up until the real
 * reservation silently rejected it at the very last step. This lets the
 * preview call site zero the discount out immediately instead, so
 * displayed === charged holds from the FIRST screen, not just the last one.
 */
export async function couponAccountEligibilityError(opts: {
  userId: string;
  firstTimeOnly: boolean;
  excludeActiveCustomers: boolean;
}): Promise<string | null> {
  if (opts.firstTimeOnly) {
    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
    if (prior > 0) return "This code is for first-time customers only.";
  }
  if (opts.excludeActiveCustomers) {
    const active = await db.server.count({
      where: { userId: opts.userId, isFree: false, status: { not: "DELETING" } },
    });
    if (active > 0) return "This offer is for accounts with no active service.";
  }
  return null;
}

