/* ------------------------------------------------------------------ *
 * (e) The game card path carries the SOLD partner discount to fulfilment
 *     (2026-09-28): fulfilment re-quotes without the coupon, so the invoice's
 *     partner line must come from the stamped price, not the fresh quote.
 * ------------------------------------------------------------------ */

test("parseGameOrderPrice: round-trips the sold partner discount and tier", async () => {
  const { parseGameOrderPrice } = await import("../lib/game-order.ts");
  assert.deepEqual(
    parseGameOrderPrice(JSON.stringify({ chargeCents: 324, partnerDiscountCents: 325, partnerDiscountTier: "FIRST" })),
    { chargeCents: 324, partnerDiscountCents: 325, partnerDiscountTier: "FIRST" },
  );
  // Legacy sessions (no partner fields) still parse, falling back to the quote.
  assert.deepEqual(parseGameOrderPrice('{"chargeCents":649}'), { chargeCents: 649 });
  // Junk partner fields are dropped, never trusted.
  assert.deepEqual(
    parseGameOrderPrice({ chargeCents: 649, partnerDiscountCents: -5, partnerDiscountTier: "HALF" }),
    { chargeCents: 649 },
  );
});
EOF
npx tsx --test test/partner-discount.test.ts 2>&1 | grep -E "^not ok|^# (pass|fail)"

